def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[^\s]")
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "NEG": 3,
        ":": 4,
    }

    def integer(text):
        text = text.strip()
        sign = 1
        if text[0] in "+-":
            if text[0] == "-":
                sign = -1
            text = text[1:]
        value = 0
        for start in range(0, len(text), 9):
            chunk = text[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return sign * value

    def parse(content):
        content = content.strip()
        if not content.startswith("="):
            return ("number", integer(content))

        nodes = []
        operators = []
        comma_counts = []
        expecting_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "NEG":
                nodes.append(("negate", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append(("binary", op, left, right))

        for token in token_pattern.findall(content[1:]):
            if token[0].isdigit():
                nodes.append(("number", integer(token)))
                expecting_operand = False
            elif token in functions:
                operators.append(token)
                expecting_operand = True
            elif token[0].isalpha():
                nodes.append(("reference", token))
                expecting_operand = False
            elif token == "(":
                operators.append("(")
                comma_counts.append(0)
                expecting_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                comma_counts[-1] += 1
                expecting_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = comma_counts.pop() + 1
                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = tuple(nodes[-count:])
                    del nodes[-count:]
                    nodes.append(("function", function, arguments))
                expecting_operand = False
            else:
                op = "NEG" if token == "-" and expecting_operand else token
                while operators and operators[-1] in precedence:
                    top = operators[-1]
                    if precedence[top] < precedence[op]:
                        break
                    if top == op == "NEG":
                        break
                    reduce_operator()
                operators.append(op)
                expecting_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def argument_nodes(arguments):
        for node in arguments:
            if node[0] == "binary" and node[1] == ":":
                first = node[2][1]
                last = node[3][1]
                col_lo, col_hi = sorted((ord(first[0]), ord(last[0])))
                row_lo, row_hi = sorted((int(first[1:]), int(last[1:])))
                for row in range(row_lo, row_hi + 1):
                    for col in range(col_lo, col_hi + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            yield ("reference", name)
            else:
                yield node

    values = {}
    active = set()

    for root in cells:
        if root in values:
            continue

        tasks = [("evaluate", ("reference", root))]
        result = 0

        while tasks:
            task = tasks.pop()
            action = task[0]

            if action == "evaluate":
                node = task[1]
                kind = node[0]

                if kind == "number":
                    result = node[1]

                elif kind == "reference":
                    name = node[1]
                    if name not in cells:
                        result = 0
                    elif name in values:
                        result = values[name]
                    elif name in active:
                        result = "#CYCLE!"
                    else:
                        active.add(name)
                        tasks.append(("finish_cell", name))
                        tasks.append(("evaluate", parse(cells[name])))

                elif kind == "negate":
                    tasks.append(("negate",))
                    tasks.append(("evaluate", node[1]))

                elif kind == "binary":
                    tasks.append(("left_done", node[1], node[3]))
                    tasks.append(("evaluate", node[2]))

                else:
                    function, arguments = node[1], node[2]
                    if function == "IF":
                        tasks.append(("choose", arguments[1], arguments[2]))
                        tasks.append(("evaluate", arguments[0]))
                    else:
                        tasks.append((
                            "aggregate_next",
                            function,
                            argument_nodes(arguments),
                            None,
                        ))

            elif action == "finish_cell":
                name = task[1]
                values[name] = result
                active.remove(name)

            elif action == "negate":
                if not isinstance(result, str):
                    result = -result

            elif action == "left_done":
                if not isinstance(result, str):
                    tasks.append(("right_done", task[1], result))
                    tasks.append(("evaluate", task[2]))

            elif action == "right_done":
                if isinstance(result, str):
                    continue

                op, left, right = task[1], task[2], result

                if op == "+":
                    result = left + right
                elif op == "-":
                    result = left - right
                elif op == "*":
                    result = left * right
                elif op == "/":
                    if right == 0:
                        result = "#DIV/0!"
                    else:
                        quotient = abs(left) // abs(right)
                        result = -quotient if (left < 0) != (right < 0) else quotient
                elif op == "=":
                    result = int(left == right)
                elif op == "<>":
                    result = int(left != right)
                elif op == "<":
                    result = int(left < right)
                elif op == "<=":
                    result = int(left <= right)
                elif op == ">":
                    result = int(left > right)
                elif op == ">=":
                    result = int(left >= right)

            elif action == "choose":
                if not isinstance(result, str):
                    tasks.append(("evaluate", task[1] if result else task[2]))

            elif action == "aggregate_next":
                function, iterator, accumulated = task[1:]
                node = next(iterator, None)
                if node is None:
                    result = 0 if accumulated is None else accumulated
                else:
                    tasks.append((
                        "aggregate_done", function, iterator, accumulated
                    ))
                    tasks.append(("evaluate", node))

            elif action == "aggregate_done":
                if isinstance(result, str):
                    continue

                function, iterator, accumulated = task[1:]
                if accumulated is None:
                    accumulated = result
                elif function == "SUM":
                    accumulated += result
                elif function == "MIN":
                    accumulated = min(accumulated, result)
                else:
                    accumulated = max(accumulated, result)

                tasks.append((
                    "aggregate_next", function, iterator, accumulated
                ))

    return {name: values[name] for name in cells}
